// Model kit — the runtime of the baked prop layer (plan: model-integration, BAKE stream). It turns a baked module record
// (assets/props/baked/<family>.ts, generated by scripts/bake/ from models/manifest.json) into an Object3D, synchronously, inside a
// registry prop's create(it, ctx), and installs those props into the registry in place (assets/props/baked.ts is the one caller).
//
// What a baked model is: geometry (quantised, no UVs, no normals, no textures) split into at most six parts, one per ROLE, and nothing
// else. A role is a material recipe resolved at create(): a house role colour (`wood`, `fabric`, `metal` ... read from ctx.colors, exactly
// what a procedural prop paints with, so kit.theme() treats the part identically) or a fixed literal (`rubber`, `cardboard`, `mirror` ...,
// flagged userData.muted so the kit's restraint pass keeps it).
//
// The rules (CLAUDE.md determinism, prop-system contract):
//  - create() is synchronous and pure: nothing async, no clock, no Math.random. A baked prop draws no rng at all, except to pick between
//    the variants of one type (one draw, from the item's own stream), so no other prop's stream can move.
//  - materials are FRESH on every call and never cached (kit.theme mutates them); geometry is shared and immutable, built once per
//    (model, size) and per THREE instance. Stretched sizes are separate geometries keyed by their size.
//  - every part is opaque, one-sided, with no `map`, no UVs and no alphaTest: GTAO sees real geometry and kit.theme() never skips it.
//  - a replaced type keeps its registry slot (Map order, footprint, height, params, tags, iso, placement all inherited), so catalog order,
//    the composer's picks and every prop's per-instance seed are untouched; the procedural builder stays as the fallback.
//  - kill switches: ?baked=0 (no baked model anywhere), ?baked=all (also the models still marked disabled, for review sheets), ?baked-off=<id,id>
//    (those models only), and `enabled: false` on a manifest entry (the committed per-model removal switch).
//
// THREE-free and dependency-free at import time (Node scripts and tests import it); the page's THREE arrives as ctx.THREE.

export type Role = string;
export interface BakedPart { role: Role; cp?: 1; n: number; nv: number; iw: 1 | 2; bb: number[]; pos: string; idx: string }
/** One stretchable axis: the middle band (between band[0] and band[1], in the model's own metres) takes the size change; the rest moves rigidly. */
export interface BakedFit { axis: 'x' | 'y' | 'z'; native: number; band: [number, number]; range: [number, number]; anchor?: 'mid' | 'min' | 'max' }
export interface BakedModel {
  v: 1; sha: string; id: string; type: string; action: 'add' | 'replace'; enabled: boolean;
  params: string[]; tags: string[]; mountY?: number; surface?: boolean;
  box: number[];                                   // x0 y0 z0 x1 y1 z1 at the default size
  fit?: { w?: BakedFit; d?: BakedFit; h?: BakedFit };
  scaleRange?: [number, number];                   // allowed `scale` param (uniform), when the model lists it
  iso?: Array<{ shape: string; box: number[]; color: string }>;
  parts: BakedPart[];
}

// ---- roles -----------------------------------------------------------------------------------------------------------------------
interface RoleSpec { from?: string; fallback?: string; fixed?: number; rough: number; metal?: number }
/** Role -> material recipe. `from` reads ctx.colors[from] (falling back to colors[fallback]); `fixed` is a literal, flagged muted. */
export const ROLES: Record<Role, RoleSpec> = {
  wood: { from: 'wood', rough: 0.55 },
  wood2: { from: 'wood2', fallback: 'wood', rough: 0.55 },
  cabinet: { from: 'cabinet', rough: 0.6 },
  fabric: { from: 'fabric', rough: 0.92 },
  fabric2: { from: 'fabric2', rough: 0.9 },
  linen: { from: 'linen', rough: 0.9 },
  rug: { from: 'rug', rough: 0.95 },
  accent: { from: 'accent', rough: 0.7 },
  ceramic: { from: 'ceramic', fallback: 'linen', rough: 0.3 },
  metal: { from: 'metal', rough: 0.35, metal: 0.8 },
  rubber: { fixed: 0x1f2328, rough: 0.7 },
  cardboard: { fixed: 0xc79f7e, rough: 0.9 },
  terracotta: { fixed: 0xc2703e, rough: 0.85 },
  glassOpaque: { fixed: 0x2b3a44, rough: 0.08, metal: 0.2 },
  mirror: { fixed: 0xe2e8f0, rough: 0.08, metal: 0.9 },       // the repo's own mirrorMat (bathroom.ts)
};
/** The colour a role has in the iso twin and the review sheets: the kit's role name for house roles, a hex for fixed ones. */
export const roleIsoColor = (role: Role): string => { const r = ROLES[role]; return r && r.fixed !== undefined ? '#' + r.fixed.toString(16).padStart(6, '0') : 'role:' + role; };

// ---- switches --------------------------------------------------------------------------------------------------------------------
export type BakedMode = '0' | '1' | 'all';
let forced: BakedMode | null = null;
let forcedOff: Set<string> | null = null;
let seenSearch: string | null = null, seenMode: BakedMode = '1', seenOff: Set<string> = new Set();
const G: any = globalThis;

/** Node scripts and tests set the mode directly; the page reads ?baked= (and ?baked-off=). null puts the URL back in charge. */
export function setBakedMode(mode: BakedMode | null, off: Iterable<string> | null = null): void { forced = mode; forcedOff = off ? new Set(off) : null; }
function readUrl(): void {
  const search = G.location && typeof G.location.search === 'string' ? G.location.search : '';
  if (search === seenSearch) return;
  seenSearch = search; seenMode = '1'; seenOff = new Set();
  try {
    const q = new URLSearchParams(search), b = q.get('baked');
    if (b === '0' || b === 'off' || b === 'false') seenMode = '0'; else if (b === 'all') seenMode = 'all';
    for (const id of (q.get('baked-off') || '').split(',')) if (id) seenOff.add(id);
  } catch { /* no URL machinery: the defaults stand */ }
}
export function bakedMode(): BakedMode { if (forced) return forced; readUrl(); return seenMode; }
const isOff = (id: string): boolean => { if (forcedOff) return forcedOff.has(id); readUrl(); return seenOff.has(id); };
/** Whether a model is served right now (the kill switches and its own `enabled`). */
export const modelActive = (m: BakedModel): boolean => { const mode = bakedMode(); return mode !== '0' && !isOff(m.id) && (m.enabled || mode === 'all'); };
const countFallback = (): void => { G.__bakedFallbacks = (G.__bakedFallbacks || 0) + 1; };

/** The lazy-chunk seam: wave B1 is statically imported, so there is nothing to load. Every build call site awaits it from day one
 *  (scripts/test-baked.mts greps for them), so a family can move to a dynamic import() later without touching a harness. */
export async function ensureBaked(_types?: Iterable<string>): Promise<void> { /* no-op while every family is eager */ }

// ---- decode and stretch ----------------------------------------------------------------------------------------------------------
interface Decoded { pos: Float32Array; idx: Uint8Array | Uint16Array; bb: number[] }
const decoded = new Map<string, Decoded[]>();     // by model sha: immutable data, safe to share across houses and THREE instances
function bytes(s: string): Uint8Array { const bin = atob(s), u = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i); return u; }
export function decodeModel(m: BakedModel): Decoded[] {
  let d = decoded.get(m.sha);
  if (d) return d;
  d = m.parts.map(p => {
    const q = bytes(p.pos), ib = bytes(p.idx), nv = p.nv, bb = p.bb, pos = new Float32Array(nv * 3);
    for (let i = 0; i < nv; i++) for (let a = 0; a < 3; a++) pos[i * 3 + a] = bb[a] + ((q[(i * 3 + a) * 2] | (q[(i * 3 + a) * 2 + 1] << 8)) / 65535) * (bb[3 + a] - bb[a]);
    let idx: Uint8Array | Uint16Array;
    if (p.iw === 1) idx = ib; else { idx = new Uint16Array(p.n * 3); for (let i = 0; i < idx.length; i++) idx[i] = ib[i * 2] | (ib[i * 2 + 1] << 8); }
    return { pos, idx, bb };
  });
  decoded.set(m.sha, d);
  return d;
}

/** The size change along one axis: which part of the span moves how far. Linear in the size, so catalog fit lines hold exactly. */
function stretchAxis(v: number, f: BakedFit, delta: number): number {
  const k = f.anchor === 'min' ? 1 : f.anchor === 'max' ? 0 : 0.5;            // the share of delta the high side takes
  const [lo, hi] = f.band;
  if (v >= hi) return v + k * delta;
  if (v <= lo) return v + (k - 1) * delta;
  return lo + (k - 1) * delta + ((v - lo) / (hi - lo)) * ((hi - lo) + delta);
}

/** The sizes a create() will build for: null when a param is outside its range and the model cannot serve it. */
export interface Sizing { w: number; d: number; h: number; s: number }
export function sizingFor(m: BakedModel, it: any, clamp: boolean): Sizing | null {
  const out: Sizing = { w: 0, d: 0, h: 0, s: 1 };
  for (const [param, f] of [['w', m.fit && m.fit.w], ['d', m.fit && m.fit.d], ['h', m.fit && m.fit.h]] as const) {
    if (!f || !m.params.includes(param)) { out[param] = f ? f.native : 0; continue; }
    let v = typeof it[param] === 'number' && it[param] > 0 ? it[param] : f.native;
    if (v < f.range[0] - 1e-9 || v > f.range[1] + 1e-9) { if (!clamp) return null; v = Math.min(f.range[1], Math.max(f.range[0], v)); }
    out[param] = v;
  }
  if (m.params.includes('scale') && typeof it.scale === 'number' && it.scale > 0) {
    const r = m.scaleRange || [0.5, 2];
    let s = it.scale; if (s < r[0] - 1e-9 || s > r[1] + 1e-9) { if (!clamp) return null; s = Math.min(r[1], Math.max(r[0], s)); }
    out.s = s;
  }
  return out;
}

const geoms = new WeakMap<object, Map<string, any[]>>();    // per THREE instance: model sha + size -> one BufferGeometry per part
function geometriesFor(THREE: any, m: BakedModel, z: Sizing): any[] {
  let byThree = geoms.get(THREE); if (!byThree) geoms.set(THREE, byThree = new Map());
  const r4 = (v: number) => Math.round(v * 1e4) / 1e4, key = `${m.sha}|${r4(z.w)}|${r4(z.d)}|${r4(z.h)}|${r4(z.s)}`;
  let g = byThree.get(key);
  if (g) return g;
  const parts = decodeModel(m), fits: Array<[number, BakedFit, number]> = [];
  if (m.fit) for (const [param, ai] of [['w', 0], ['h', 1], ['d', 2]] as const) { const f = m.fit[param]; const size = z[param]; if (f && size && Math.abs(size - f.native) > 1e-9) fits.push([ai, f, size - f.native]); }
  g = parts.map(p => {
    let pos = p.pos;
    if (fits.length || z.s !== 1) {
      pos = new Float32Array(p.pos);
      for (let i = 0; i < pos.length; i += 3) {
        for (const [ai, f, delta] of fits) pos[i + ai] = stretchAxis(pos[i + ai], f, delta);
        if (z.s !== 1) { pos[i] *= z.s; pos[i + 1] *= z.s; pos[i + 2] *= z.s; }
      }
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setIndex(new THREE.BufferAttribute(p.idx, 1));
    geo.computeVertexNormals();                  // hard edges were split at bake time, so this is crisp where it should be and smooth on curves
    return geo;
  });
  byThree.set(key, g);
  return g;
}

const humanise = (type: string) => type.split('-').map(w => w[0].toUpperCase() + w.slice(1)).join(' ');

/** Build one baked model: a group of one mesh per role part, materials fresh. `clamp` pins an out-of-range size to the range (a type with no
 *  procedural fallback); with clamp off an out-of-range size returns null and the caller falls back. */
export function buildBaked(m: BakedModel, it: any, ctx: any, clamp = false): any {
  const { THREE, std, hex, colors, group } = ctx;
  const z = sizingFor(m, it, clamp);
  if (!z) return null;
  const geo = geometriesFor(THREE, m, z), g = group(humanise(m.type));
  g.userData.bakedId = m.id;
  m.parts.forEach((p, i) => {
    const spec = ROLES[p.role];
    if (!spec) throw new Error(`baked ${m.id}: unknown role "${p.role}"`);
    let color: number;
    if (spec.fixed !== undefined) color = spec.fixed;
    else { const c = colors[spec.from!] ?? (spec.fallback ? colors[spec.fallback] : undefined); if (c === undefined) throw new Error(`baked ${m.id}: the kit has no colour for role "${p.role}"`); color = c; }
    if (p.cp && it.color !== undefined) color = hex(it.color);
    const mat = std(color, spec.metal !== undefined ? { roughness: spec.rough, metalness: spec.metal } : { roughness: spec.rough });
    mat.name = 'role:' + p.role;
    if (spec.fixed !== undefined) mat.userData.muted = true;
    if (p.cp) mat.userData.colorParam = true;
    const mesh = new THREE.Mesh(geo[i], mat);
    mesh.name = 'part:' + p.role; mesh.castShadow = true; mesh.receiveShadow = true;
    g.add(mesh);
  });
  return g;
}

// ---- the registry hook -----------------------------------------------------------------------------------------------------------
/** Install baked models into a registry Map, in place. A `replace` model keeps its type's slot and every inherited field (so Map order,
 *  propIndex counts and seeds cannot move); the procedural create stays as the fallback. An `add` model registers a new type (appended).
 *  Models of one type are variants: one rng draw from the item's own stream picks between them. */
export function installBaked(PROPS: Map<string, any>, models: BakedModel[]): void {
  const byType = new Map<string, BakedModel[]>();
  for (const m of models) { const l = byType.get(m.type); if (l) l.push(m); else byType.set(m.type, [m]); }
  for (const [type, list] of byType) {
    const replace = list.every(m => m.action === 'replace');
    if (!replace && !list.every(m => m.action === 'add')) throw new Error(`baked: "${type}" mixes add and replace models`);
    const old = PROPS.get(type);
    if (replace && !old) throw new Error(`baked: no procedural prop "${type}" to replace`);
    if (!replace && old && !old.bakedId) throw new Error(`baked: "${type}" is a new type but the registry already has it`);
    const procedural = old && old.bakedId ? old.procedural : old;     // installing twice must not stack overrides
    const head = list[0];
    const create = (it: any, ctx: any) => {
      const active = list.filter(modelActive);
      try {
        if (active.length) {
          const m = active.length === 1 ? active[0] : active[Math.min(active.length - 1, Math.floor(ctx.rng() * active.length))];
          const o = buildBaked(m, it, ctx, !procedural);
          if (o) return o;
          if (!procedural) throw new Error('out of range');
        }
      } catch (e) { countFallback(); if (!procedural) { const g = ctx.group(humanise(type)); g.userData.bakedFailed = String((e as Error).message || e); return g; } }
      if (procedural) return procedural.create(it, ctx);
      const g = ctx.group(humanise(type)); g.userData.bakedOff = true; return g;     // a new type with its models off: an empty group, nothing to fall back to
    };
    if (replace) { PROPS.set(type, { ...procedural, bakedId: head.id, bakedIds: list.map(m => m.id), procedural, create }); continue; }
    const [x0, y0, z0, x1, y1, z1] = head.box;
    PROPS.set(type, {
      // the registry's own defaults (registry.ts registerProps), then the model's: footprint and height are the baked box's
      surface: false, foliage: false,
      footprint: [+(x1 - x0).toFixed(3), +(z1 - z0).toFixed(3)], height: +(y1 - y0).toFixed(3),
      ...(head.surface ? { surface: true } : {}), ...(head.mountY !== undefined ? { mountY: head.mountY } : {}),
      params: head.params, tags: head.tags, ...(head.iso ? { iso: head.iso } : {}),
      bakedId: head.id, bakedIds: list.map(m => m.id), procedural: null, create,
    });
  }
}
